mapper.update:
update ${prefix}FLW_EVENT_INSTANCE

    CATEGORY_ = #{eventCategory, jdbcType=NVARCHAR},

where ID_ = #{id, jdbcType=VARCHAR}

mapper.sql:

from ${prefix}FLW_EVENT_INSTANCE RES


    RES.ID_ = #{id, jdbcType=VARCHAR}


    and RES.EVENT_KEY_ = #{eventKey, jdbcType=VARCHAR}


    and RES.EVENT_KEY_ like #{eventKeyLike, jdbcType=VARCHAR}


    and lower(RES.EVENT_KEY_) like lower(#{eventKeyLikeIgnoreCase, jdbcType=VARCHAR}${wildcardEscapeClause})


    and RES.EVENT_DEFINITION_KEY_ = #{eventDefinitionKey, jdbcType=VARCHAR}


    and RES.CATEGORY_ = #{eventCategory, jdbcType=NVARCHAR}


    and RES.CATEGORY_ like #{eventCategoryLike, jdbcType=NVARCHAR}


    and ( RES.CATEGORY_ <> #{eventCategoryNotEquals, jdbcType=NVARCHAR} OR RES.CATEGORY_ is null )


    and RES.TENANT_ID_ = #{tenantId, jdbcType=VARCHAR}


    and RES.TENANT_ID_ like #{tenantIdLike, jdbcType=VARCHAR}


    and (RES.TENANT_ID_ = '' or RES.TENANT_ID_ is null)
